4. // FixedSizeBumpAllocator - Proofs
5. //
6. // Proof-function signatures for the abstract pool model. Bodies are `admit()`
7. // placeholders during the specification phase; the proving phase discharges them.
8. // Each lemma encodes a caller expectation from
9. // `verus-ai-logs/nanvix-phys-bump-allocator/caller_analysis.md`.
10. 
11. verus! {
12. 
13. //==================================================================================================
14. // Geometry lemmas (uniqueness / in-bounds / alignment)
15. //==================================================================================================
16. 
17. /// A well-formed pool satisfies all three geometric guarantees: every slot is
18. /// `unit_align`-aligned, lies fully inside the backing region, and is distinct
19. /// from every other slot.
20. ///
21. /// Backs caller invariants: *Alignment*, *In-bounds*, *Uniqueness / non-aliasing*.
22. pub proof fn lemma_geometry(v: BumpView)
23.     requires
24.         v.inv(),
25.     ensures
26.         v.geometry_ok(),
27. {
28.     let a: int = v.unit_align as int;
29.     let s: int = v.stride as int;
30.     let b: int = v.base as int;
31.     let us: int = v.unit_size as int;
32.     let cap: int = v.capacity as int;
33.     let ss: int = v.storage_size as int;
34. 
35.     // `stride` is an exact multiple of `unit_align`: s == a * (s / a).
36.     let q: int = s / a;
37.     vstd::arithmetic::div_mod::lemma_fundamental_div_mod(s, a);
38.     assert(s == a * q);
39. 
40.     // (a) Every slot start is `unit_align`-aligned.
41.     assert forall|i: int| 0 <= i < cap implies #[trigger] v.slot_addr(i) % a == 0 by {
42.         // i * s == a * (i * q), so slot_addr(i) == a * (i * q) + b.
43.         assert(i * s == a * (i * q)) by (nonlinear_arith)
44.             requires
45.                 s == a * q,
46.         ;
47.         vstd::arithmetic::div_mod::lemma_mod_multiples_vanish(i * q, b, a);
48.     }
49. 
50.     // (b) Every slot lies fully inside the backing region.
51.     assert forall|i: int| 0 <= i < cap implies {
52.         &&& v.base <= #[trigger] v.slot_addr(i)
53.         &&& v.slot_addr(i) + us <= v.base + ss
54.     } by {
55.         // Lower bound: i * s >= 0.
56.         vstd::arithmetic::mul::lemma_mul_nonnegative(i, s);
57.         // Upper bound: i * s + us <= (i + 1) * s <= cap * s <= ss.
58.         assert((i + 1) * s == i * s + s) by {
59.             vstd::arithmetic::mul::lemma_mul_is_distributive_add_other_way(s, i, 1);
60.         }
61.         vstd::arithmetic::mul::lemma_mul_inequality(i + 1, cap, s);
62.     }
63. 
64.     // (c) Distinct indices map to distinct addresses.
65.     assert forall|i: int, j: int|
66.         (0 <= i < cap && 0 <= j < cap && i != j) implies (#[trigger] v.slot_addr(i)) != (
67.     #[trigger] v.slot_addr(j)) by {
68.         if i < j {
69.             vstd::arithmetic::mul::lemma_mul_strict_inequality(i, j, s);
70.         } else {
71.             vstd::arithmetic::mul::lemma_mul_strict_inequality(j, i, s);
72.         }
73.     }
74. }
75. 
76. //==================================================================================================
77. // Capacity / transition lemmas (monotone capacity, no spurious consumption)
78. //==================================================================================================
79. 
80. /// The exhaustion boundary is exactly `allocated == capacity`: the pool has a free
81. /// slot iff fewer than `capacity` slots have been handed out.
82. ///
83. /// Backs caller invariant: *Monotone capacity* (the `Exhausted` boundary).
84. pub proof fn lemma_exhausted_boundary(v: BumpView)
85.     requires
86.         v.inv(),
87.     ensures
88.         !v.has_capacity() <==> v.allocated == v.capacity,
89. {
90. }
91. 
92. /// A successful allocation advances the cursor by exactly one slot and preserves
93. /// the invariant. The freshly handed-out index `v.allocated` was previously free
94. /// and becomes consumed.
95. ///
96. /// Backs caller invariants: *Monotone capacity* (advance by one), *Uniqueness*
97. /// (each index handed out at most once).
98. pub proof fn lemma_alloc_transition(v: BumpView)
99.     requires
100.         v.inv(),
101.         v.has_capacity(),
102.     ensures
103.         v.spec_alloc().inv(),
104.         v.spec_alloc().allocated == v.allocated + 1,
105.         !v.is_consumed(v.allocated as int),
106.         v.spec_alloc().is_consumed(v.allocated as int),
107.         // Configuration (everything except `allocated`) is unchanged.
108.         v.spec_alloc() == (BumpView { allocated: v.spec_alloc().allocated, ..v }),
109. {
110.     assert(v.spec_alloc() =~= (BumpView { allocated: v.spec_alloc().allocated, ..v }));
111. }
112. 
113. } // verus!
114.

